function renderSyncStatus(){const el=document.getElementById('healthText');if(!el)return;const syncAge=state.lastSync?Math.max(0,Math.round((Date.now()-state.lastSync)/1000)):null,g=state.game,final=!!(g?.completed||g?.state==='post');if(final){el.textContent=`FINAL · ARCHIVED GAME${syncAge!==null?' · checked '+syncAge+'s ago':''}`;return}const phase=g?.state==='in'?'LIVE':'PREGAME',feed=g?.feed_age_seconds;if(state.syncFailures)el.textContent=`${phase} · CONNECTION RETRY ${state.syncFailures}`;else if(feed!==null&&feed!==undefined)el.textContent=`${phase} · FEED ${feed}s OLD · checked ${syncAge??0}s ago`;else if(syncAge!==null)el.textContent=`${phase} · checked ${syncAge}s ago`; }
function pollDelay111(){let g=state.game;if(!g)return 15000;if(g.completed||g.state==='post')return 0;if(g.state==='in')return Math.max(2500,state.refresh||2500);let ko=g.date?new Date(g.date).getTime():NaN,delta=Number.isFinite(ko)?ko-Date.now():Infinity;if(delta<30*60*1000&&delta>-60*60*1000)return 15000;return 60000}
