function fmt(v,d=1){let n=Number(v);return Number.isFinite(n)?n.toFixed(d):'—'}
function teamRowData(ab){let l=FO.league||{},s=(l.standings||[]).find(x=>x.abbr===ab)||{},p=(l.teams||[]).find(x=>x.abbr===ab)||{},pow=(l.power||[]).find(x=>x.abbr===ab)||{};return {...s,...p,...pow,abbr:ab,name:s.name||p.name||TEAM_NAMES[ab]||ab}}
