function renderFrontOffice(){let b=$('#frontOfficeBody');if(!b)return;$$('#foTabs button').forEach(x=>x.classList.toggle('active',x.dataset.fotab===FO.tab));if(FO.tab==='roster'){b.innerHTML=renderRosterHQ();wirePlayerClicks();return}if(FO.tab==='matchup'){b.innerHTML=renderMatchupLab();wireMatchupLab();return}if(FO.tab==='quality'){b.innerHTML=renderDataQuality();return}if(FO.tab==='teams'){b.innerHTML=`<div class="toolbar"><select id="foTeam">${teamOptions(FO.team)}</select><input id="foSearch" placeholder="Jump to team…"></div>${teamCommand(FO.team)}`;$('#foTeam').onchange=e=>{FO.team=e.target.value;renderFrontOffice()};$('#foSearch').oninput=e=>{let q=e.target.value.toLowerCase(),x=Object.keys(TEAM_NAMES).find(a=>a.toLowerCase()===q||TEAM_NAMES[a].toLowerCase().includes(q));if(x){FO.team=x;renderFrontOffice()}};wireFavs();return}if(FO.tab==='positions'){let cats=['QB Lab','RB Lab','Receiver Lab','Trenches Lab','Pass Rush','Linebackers','Secondary'];b.innerHTML=`<div class="positionGrid">${cats.map((x,i)=>`<div class="card"><div class="cardHead"><b>${x}</b><span class="badge">ROOM ${i+1}</span></div><div class="cardBody"><p>Position-specific comparison workspace using verified player and team data.</p><button class="linkBtn" data-route="players">Open player database →</button></div></div>`).join('')}</div>`;wireRoutes();return}if(FO.tab==='situational'){let g=state.game,ps=g?.plays||[];let downs=[1,2,3,4].map(d=>{let a=ps.filter(p=>Number(p.end?.down||p.start?.down)===d),avg=a.length?a.reduce((z,p)=>z+(num(p.statYardage)||0),0)/a.length:null;return miniMetric(`${d}${d===1?'st':d===2?'nd':d===3?'rd':'th'} down`,a.length?`${a.length} plays · ${fmt(avg)} Y/P`:'—')}).join('');b.innerHTML=`<div class="grid g4">${downs}</div><div class="card" style="margin-top:14px"><div class="cardHead"><b>Situational football</b><span class="badge derived">ƒ DERIVED</span></div><div class="cardBody"><p>Down splits are calculated only from captured plays that expose down and yardage fields. Red-zone and two-minute modules stay source-gated when situation data is incomplete.</p></div></div>`;return}if(FO.tab==='trends'){let rows=(FO.league?.power||[]).slice(0,16);b.innerHTML=`<div class="card"><div class="cardHead"><b>League distribution</b><span class="badge derived">ATLAS INDEX</span></div><div class="cardBody"><div class="rankBars">${rows.map(r=>`<div><small>#${esc(r.atlasRank)} ${esc(r.abbr)}</small><i style="width:${Math.max(3,Math.min(100,Number(r.atlasIndex)||0))}%"></i><b>${esc(r.atlasIndex)}</b></div>`).join('')}</div></div></div>`;return}if(FO.tab==='inspector'){let g=state.game;b.innerHTML=`<div class="grid g3">${miniMetric('Game provider',g?.source||'—')}${miniMetric('League source',FO.league?.source||'—')}${miniMetric('League updated',FO.league?.updated?new Date(FO.league.updated*1000).toLocaleString():'—')}</div><div class="card" style="margin-top:14px"><div class="cardHead"><b>Data contract</b></div><div class="cardBody stackList"><span>Provider values → displayed as supplied</span><span>Atlas calculations → labeled ƒ DERIVED</span><span>Unavailable inputs → —</span><span>Next Gen tracking metrics → source-gated</span></div></div>`;return}if(FO.tab==='favorites'){let fav=JSON.parse(localStorage.getItem('atlasFavs')||'[]');b.innerHTML=fav.length?fav.map(teamCommand).join('<hr class="sep">'):'<div class="empty">No pinned teams yet. Open Team Command and pin one.</div>';wireFavs()}}
