function atlasSearchIndex(){let out=[];for(const [abbr,name] of Object.entries(TEAM_NAMES))out.push({kind:'TEAM',label:name,sub:abbr,action:()=>{FO.team=abbr;FO.tab='teams';route({view:'frontoffice'})}});for(const p of state.players||[])out.push({kind:'PLAYER',label:p.name||'Unknown',sub:`${p.team||'—'} · ${p.position||'—'}`,action:()=>route({view:'players'})});for(const g of state.games||[]){let a=team(g,'away'),h=team(g,'home');out.push({kind:'GAME',label:`${a.abbr} @ ${h.abbr}`,sub:g.status||'',action:()=>{route({view:'games',tab:'overview',gameId:g.id});loadSelected(g.id)}})}return out}
function showCommandPalette(){let old=$('#atlasPalette');if(old)old.remove();let el=document.createElement('div');el.id='atlasPalette';el.className='paletteShade';el.innerHTML=`<div class="palette"><div class="eyebrow">ATLAS COMMAND</div><input id="paletteInput" autofocus placeholder="Search team, player, game or page…"><div id="paletteResults" class="paletteResults"></div><small>ESC closes · CTRL/⌘ + K opens</small></div>`;document.body.appendChild(el);let input=$('#paletteInput'),res=$('#paletteResults');let pages=[['Game Center','home'],['NFL Games','games'],['Players','players'],['Analytics','analytics'],['League HQ','league'],['War Room','warroom'],['Front Office','frontoffice'],['Film Room','filmroom'],['Compare Lab','compare'],['Control Tower','control'],['Sunday Board','sunday'],['Stat Studio','studio'],['Game DNA','gamedna'],['Situation Lab','situations'],['My Atlas','dashboard'],['Archive','archive'],['About','about']];function draw(){let q=input.value.trim().toLowerCase(),items=atlasSearchIndex().filter(x=>!q||`${x.label} ${x.sub}`.toLowerCase().includes(q)).slice(0,10);let pp=pages.filter(x=>!q||x[0].toLowerCase().includes(q)).slice(0,4);res.innerHTML=pp.map(x=>`<button data-page="${x[1]}"><b>${x[0]}</b><span>PAGE</span></button>`).join('')+items.map((x,i)=>`<button data-search="${i}"><b>${esc(x.label)}</b><span>${esc(x.kind)} · ${esc(x.sub)}</span></button>`).join('');$$('[data-page]').forEach(b=>b.onclick=()=>{route({view:b.dataset.page});el.remove()});$$('[data-search]').forEach(b=>b.onclick=()=>{items[+b.dataset.search].action();el.remove()})}input.oninput=draw;el.onclick=e=>{if(e.target===el)el.remove()};draw();setTimeout(()=>input.focus(),0)}
