function renderControlTower(){let b=$('#controlBody');if(!b)return;let g=state.game,favs=JSON.parse(localStorage.getItem('atlasFavs')||'[]'),leaders=(FO.league?.leaders||[]).slice(0,8);b.innerHTML=`<div class="controlHero"><div><span class="eyebrow">ATLAS OS</span><h2>Everything one click away.</h2><p>Use <b>Ctrl/⌘ + K</b> anywhere to search Atlas.</p></div><button id="openPalette" class="commandKey">⌘K SEARCH</button></div>${g?`<div class="card controlLive"><div class="cardHead"><b>LIVE / SELECTED GAME</b><button class="linkBtn" data-route="warroom">Open War Room →</button></div><div class="cardBody">${hero(g)}</div></div>`:''}<div class="grid g2 controlGrid"><div class="card"><div class="cardHead"><b>Pinned teams</b><span class="badge">LOCAL</span></div><div class="cardBody">${favs.length?favs.map(a=>{let r=teamRowData(a);return `<button class="controlTeam" data-cteam="${a}" style="--tc:${TEAM_COLORS[a]||'#999'}"><b>${a}</b><span>${esc(r.name)}</span><em>${esc(r.record||'—')}</em></button>`}).join(''):'<div class="empty">Pin teams from Front Office to build your board.</div>'}</div></div><div class="card"><div class="cardHead"><b>Quick launch</b></div><div class="cardBody quickLaunch">${[['⌖','War Room','warroom'],['▶','Film Room','filmroom'],['◆','League HQ','league'],['▣','Front Office','frontoffice'],['⇄','Compare','compare'],['⌁','Analytics','analytics']].map(x=>`<button data-route="${x[2]}"><strong>${x[0]}</strong><span>${x[1]}</span></button>`).join('')}</div></div></div><div class="card" style="margin-top:14px"><div class="cardHead"><b>League pulse</b><span class="badge">SEASON FEED</span></div><div class="cardBody controlPulse">${leaders.length?leaders.map(x=>`<div><small>${esc(x.category||'LEADER')}</small><b>${esc(x.name||'—')}</b><span>${esc(x.team||'—')} · ${esc(x.value||'—')}</span></div>`).join(''):'<div class="empty">League leader feed unavailable.</div>'}</div></div>`;$('#openPalette').onclick=showCommandPalette;$$('[data-cteam]').forEach(x=>x.onclick=()=>{FO.team=x.dataset.cteam;FO.tab='teams';route({view:'frontoffice'})});wireRoutes()}
