function playType(p){let t=String(p?.type||p?.text||'').toLowerCase();if(t.includes('pass'))return'PASS';if(t.includes('rush')||t.includes('run'))return'RUSH';if(t.includes('punt'))return'PUNT';if(t.includes('kick'))return'KICK';if(t.includes('field goal'))return'FG';if(t.includes('sack'))return'SACK';return'OTHER'}
