function atlasPlayKind(p){let t=((p?.type||'')+' '+(p?.text||'')).toLowerCase();if(t.includes('sack'))return'SACK';if(/pass/.test(t))return'PASS';if(/rush|run|scramble/.test(t))return'RUSH';if(/field goal/.test(t))return'FG';if(/punt/.test(t))return'PUNT';if(/kick/.test(t))return'KICK';return'OTHER'}
function atlasDriveTeam(d){return d?.team||d?.teamAbbreviation||'—'}
function atlasSituationStats(g){let ps=g?.plays||[];let down=n=>ps.filter(p=>Number(p?.start?.down||p?.end?.down)===n);let third=down(3), explosive=ps.filter(p=>Math.abs(num(p.statYardage)||0)>=20), neg=ps.filter(p=>(num(p.statYardage)||0)<0);let red=ps.filter(p=>{let y=String(p?.start?.yardLine||p?.end?.yardLine||'');let m=y.match(/(\d+)/);return m&&Number(m[1])<=20});return {plays:ps.length,third:third.length,explosive:explosive.length,negative:neg.length,red:red.length,downs:[1,2,3,4].map(n=>{let a=down(n);return {n,count:a.length,y:a.reduce((s,p)=>s+(num(p.statYardage)||0),0),avg:a.length?a.reduce((s,p)=>s+(num(p.statYardage)||0),0)/a.length:null}})}}
