function renderSituationLab(){let b=$('#situationsBody'),g=state.game;if(!b)return;if(!g){b.innerHTML='<div class="empty">Select a game first.</div>';return}let s=atlasSituationStats(g),ps=g.plays||[];let kinds=['PASS','RUSH','SACK','PUNT','FG'].map(k=>[k,ps.filter(p=>atlasPlayKind(p)===k).length]);b.innerHTML=`<div class="situationGrid"><div class="situationTile"><small>RED-ZONE PLAYS</small><b>${s.red}</b></div><div class="situationTile"><small>THIRD-DOWN PLAYS</small><b>${s.third}</b></div><div class="situationTile"><small>EXPLOSIVES</small><b>${s.explosive}</b></div><div class="situationTile"><small>NEGATIVE PLAYS</small><b>${s.negative}</b></div></div><div class="grid g2" style="margin-top:14px"><div class="card"><div class="cardHead"><b>Play-Type Fingerprint</b><span class="badge derived">ƒ DERIVED</span></div><div class="cardBody splitTable">${kinds.map(([k,v])=>`<div class="splitRow"><b>${k}</b><i style="width:${Math.min(100,v*6)}%"></i><span>${v}</span><span>${ps.length?Math.round(v/ps.length*100):0}%</span></div>`).join('')}</div></div><div class="card"><div class="cardHead"><b>Down Efficiency</b><span class="badge derived">ƒ CAPTURED YARDS</span></div><div class="cardBody splitTable">${s.downs.map(x=>`<div class="splitRow"><b>DOWN ${x.n}</b><i style="width:${Math.min(100,Math.max(0,(x.avg||0)*10))}%"></i><span>${x.count}</span><span>${x.avg==null?'—':x.avg.toFixed(1)} Y/P</span></div>`).join('')}</div></div></div><div class="card" style="margin-top:14px"><div class="cardHead"><b>Situation Play Ledger</b><button class="linkBtn" data-route="filmroom">Open Film Room →</button></div><div class="cardBody liveLedger">${ps.slice(-16).reverse().map(p=>`<div><span>${esc(p.team||'—')}</span><b>${atlasPlayKind(p)}</b><em>${esc(p.statYardage??'—')} YDS</em><small>Q${esc(p.period||'—')} ${esc(p.clock||'')}</small><p>${esc(p.text||'')}</p></div>`).join('')||'<div class="empty">No plays captured.</div>'}</div></div>`}
