function teamUniverseCard10(ab,d){let r=(d.standings||[]).find(x=>x.abbr===ab)||{}, sample=(d.teams||[]).find(x=>x.abbr===ab)||{}, pow=(d.power||[]).find(x=>x.abbr===ab)||{}, leaders=(d.teamLeaders||{})[ab]||[];return `<div class="universeHero" style="--tc:${TEAM_COLORS[ab]||'#6ee7ff'}"><div><span class="eyebrow">${esc(r.division||'NFL TEAM')}</span><h2>${esc(TEAM_NAMES[ab]||ab)}</h2><p>${esc(r.record||'—')} · ${esc(r.conference||'')} · Atlas sample ${esc(sample.games||0)} game(s)</p></div><div class="universeRank"><small>ATLAS INDEX</small><b>${esc(pow.atlasIndex??'—')}</b><span>${pow.atlasRank?'#'+esc(pow.atlasRank):'—'}</span></div></div><div class="grid g4 omniStats">${miniMetric('PF / game',sample.ppg==null?'—':sample.ppg.toFixed(1))}${miniMetric('Yards / game',sample.ypg==null?'—':sample.ypg.toFixed(1))}${miniMetric('Yards allowed',sample.yapg==null?'—':sample.yapg.toFixed(1))}${miniMetric('Takeaways',sample.takeaways??'—')}</div><div class="grid g2" style="margin-top:14px"><div class="card"><div class="cardHead"><b>Team leaders</b><span class="badge">SEASON</span></div><div class="cardBody">${leaders.length?leaders.slice(0,8).map(x=>`<div class="teamLeaderRow"><small>${esc(x.category)}</small><b>${esc(x.name)}</b><strong>${esc(x.value)}</strong></div>`).join(''):'<div class="empty">Season leader feed unavailable.</div>'}</div></div><div class="card"><div class="cardHead"><b>Open workspaces</b></div><div class="cardBody quickLaunch"><button data-tu="roster"><strong>▦</strong><span>Roster HQ</span></button><button data-tu="matchup"><strong>⇄</strong><span>Matchup Lab</span></button><button data-tu="trends"><strong>⌁</strong><span>Trends</span></button><button data-route="league"><strong>◆</strong><span>League context</span></button></div></div></div>`}
