function playExplorerRows10(ps){return ps.slice().reverse().slice(0,120).map(p=>`<div class="play10"><div><b>${esc(p.team||'—')}</b><span>Q${esc(p.period||'—')} ${esc(p.clock||'')}</span><em>${esc(atlasPlayKind(p))}</em><strong>${esc(p.statYardage??'—')} YD</strong></div><p>${esc(p.text||'')}</p></div>`).join('')||'<div class="empty">No captured plays match these filters.</div>'}
function scoringAnatomy10(g){let ps=g?.plays||[], scores=ps.filter(p=>p.scoringPlay), byQ=[1,2,3,4,5].map(q=>[q,scores.filter(p=>+p.period===q).length]), explosive=ps.filter(p=>Math.abs(num(p.statYardage)||0)>=20).length, neg=ps.filter(p=>(num(p.statYardage)||0)<0).length, sacks=ps.filter(p=>atlasPlayKind(p)==='SACK').length;return `<div class="grid g4">${miniMetric('Scoring plays',scores.length)}${miniMetric('Explosives 20+',explosive)}${miniMetric('Negative plays',neg)}${miniMetric('Sacks captured',sacks)}</div><div class="card" style="margin-top:14px"><div class="cardHead"><b>Scoring by quarter · captured PBP</b><span class="badge derived">ƒ STRUCTURE</span></div><div class="cardBody splitTable">${byQ.filter(x=>x[1]||x[0]<=4).map(([q,n])=>`<div class="splitRow"><b>Q${q}</b><i style="width:${Math.min(100,n*25)}%"></i><span>${n}</span><span>scoring plays</span></div>`).join('')}</div></div>`}
