function renderLab10(){let b=$('#lab10Body'),g=state.game;if(!b)return;let tabs=[['explorer','Play Explorer'],['drives','Drive Lab'],['situations','Situational Matrix'],['scoring','Scoring Anatomy'],['deep','Deep Tools']];let head=`<div class="lab10Tabs">${tabs.map(([k,n])=>`<button class="${ATLAS10.lab===k?'active':''}" data-lab10="${k}">${n}</button>`).join('')}</div>`;if(!g){b.innerHTML=head+'<div class="empty">Select a game from Live or Scoreboard to activate Atlas Lab.</div>';wireLab10();return}if(ATLAS10.lab==='explorer'){b.innerHTML=head+`<div class="toolbar"><input id="pxSearch" placeholder="Search play text…"><select id="pxTeam"><option value="">All teams</option>${g.teams.map(t=>`<option>${esc(t.abbr)}</option>`).join('')}</select><select id="pxType"><option value="">All play types</option>${['PASS','RUSH','SACK','PUNT','KICK','FG','OTHER'].map(x=>`<option>${x}</option>`).join('')}</select><select id="pxDown"><option value="">All downs</option>${[1,2,3,4].map(x=>`<option value="${x}">${x}</option>`).join('')}</select><label class="check10"><input type="checkbox" id="pxExplosive">20+ yards</label></div><div class="playExplorer10" id="pxRows">${playExplorerRows10(g.plays||[])}</div>`;let run=()=>{let q=$('#pxSearch').value.toLowerCase(),tm=$('#pxTeam').value,ty=$('#pxType').value,dn=$('#pxDown').value,ex=$('#pxExplosive').checked,ps=(g.plays||[]).filter(p=>(!q||String(p.text||'').toLowerCase().includes(q))&&(!tm||p.team===tm)&&(!ty||atlasPlayKind(p)===ty)&&(!dn||String(p.start?.down||p.end?.down||'')===dn)&&(!ex||Math.abs(num(p.statYardage)||0)>=20));$('#pxRows').innerHTML=playExplorerRows10(ps)};['#pxSearch','#pxTeam','#pxType','#pxDown','#pxExplosive'].forEach(x=>{let e=$(x);if(e)e.oninput=run})}else if(ATLAS10.lab==='drives')b.innerHTML=head+driveLab10(g);else if(ATLAS10.lab==='situations'){let s=atlasSituationStats(g);b.innerHTML=head+`<div class="grid g4">${miniMetric('Red-zone plays',s.red)}${miniMetric('Third-down plays',s.third)}${miniMetric('Explosives',s.explosive)}${miniMetric('Negative plays',s.negative)}</div><div class="card" style="margin-top:14px"><div class="cardHead"><b>Down × efficiency matrix</b><span class="badge derived">ƒ CAPTURED YARDS</span></div><div class="cardBody situationMatrix10">${s.downs.map(x=>`<div><small>DOWN ${x.n}</small><b>${x.avg==null?'—':x.avg.toFixed(1)}</b><span>yards/play</span><em>${x.count} plays</em></div>`).join('')}</div></div>`}else if(ATLAS10.lab==='scoring')b.innerHTML=head+scoringAnatomy10(g);else b.innerHTML=head+`<div class="toolGrid10">${[['War Room','warroom','Dense live intelligence'],['Stat Studio','studio','Custom game metrics'],['Game DNA','gamedna','Forensic game shape'],['Situation Lab','situations','Down + zone splits'],['Film Room','filmroom','Drive and play browser'],['Compare','compare','Side-by-side team context'],['Analytics','analytics','Core game analytics'],['Archive','archive','Stored game history']].map(([n,r,d])=>`<button data-route="${r}"><b>${n}</b><span>${d}</span><em>OPEN →</em></button>`).join('')}</div>`;wireLab10();wireRoutes()}
