function atlasExportGame10(){let g=state.game;if(!g)return;let rows=[['period','clock','team','type','yards','text'],...(g.plays||[]).map(p=>[p.period,p.clock,p.team,atlasPlayKind(p),p.statYardage,p.text])];let csv=rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\n'),blob=new Blob([csv],{type:'text/csv'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`gridiron-atlas-${g.id}-plays.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
