function prime101RosterShell(ab){return `<div class="primeRosterHead"><div><span class="eyebrow">ACTIVE ROSTER + DEPTH CHART</span><h2>${esc(TEAM_NAMES[ab]||ab)}</h2><p>Roster biographical fields come from the connected roster feed. ★ marks a verified rank-1 depth-chart entry.</p></div><select id="rosterTeam">${teamOptions(ab)}</select></div><div id="primeRosterBody"><div class="empty">Importing ${esc(ab)} roster + depth chart…</div></div>`}
