function posBucket101(p){let q=String(p.position||'').toUpperCase();if(['T','G','C','OT','OG','OL'].includes(q))return'OL';if(['DE','DT','NT','DL'].includes(q))return'DL';if(['CB','S','FS','SS','DB'].includes(q))return'DB';if(['K','P','LS','KR','PR'].includes(q))return'ST';return ['QB','RB','WR','TE','LB'].includes(q)?q:'OTHER'}
function renderRoster101(d){let box=$('#primeRosterBody');if(!box)return;let ps=d.players||[],groups={QB:[],RB:[],WR:[],TE:[],OL:[],DL:[],LB:[],DB:[],ST:[],OTHER:[]};ps.forEach(p=>groups[posBucket101(p)].push(p));box.innerHTML=`<div class="primeRosterStats"><div><b>${ps.length}</b><span>players imported</span></div><div><b>${d.starters||0}</b><span>rank-1 depth entries</span></div><div><b>${Object.values(groups).filter(x=>x.length).length}</b><span>position rooms</span></div><div><b>${esc(d.source||'ROSTER FEED')}</b><span>source</span></div></div><div class="rosterBoard primeRosterBoard">${Object.entries(groups).filter(([,v])=>v.length).map(([k,v])=>`<div class="card"><div class="cardHead"><b>${k}</b><span>${v.length}</span></div><div class="cardBody rosterList">${v.sort((a,b)=>(b.starter-a.starter)||((a.depth_rank||99)-(b.depth_rank||99))||String(a.name).localeCompare(String(b.name))).map(p=>`<button class="playerLink primePlayer" data-prime-player="${esc(p.id||'')}" data-prime-name="${esc(p.name)}"><img src="${esc(p.headshot||playerImg(p))}" onerror="this.style.display='none'"><span><b>${p.starter?'<i class="starterStar">★</i> ':''}${esc(p.name)}</b><small>#${esc(p.jersey||'—')} · ${esc(p.position||k)}${p.depth_rank?' · DEPTH '+esc(p.depth_rank):''}</small><em>${esc(p.experience==null?'—':p.experience)} yr · ${esc(p.college||'College —')}</em></span></button>`).join('')}</div></div>`).join('')}</div>`;wirePrimePlayerButtons101()}
