const _loadPlayerDb101=loadPlayerDb;
loadPlayerDb=async function(){let db=$('#playerDb');if(db)db.innerHTML='<div class="empty">Importing all 32 NFL rosters… first load can take a moment.</div>';try{let d=await api('/api/players?_='+Date.now());state.players=d.players||[];let teams=[...new Set(state.players.map(x=>x.team).filter(Boolean))].sort(),pos=[...new Set(state.players.map(x=>x.position).filter(Boolean))].sort();$('#playerTeam').innerHTML='<option value="">All 32 teams</option>'+teams.map(x=>`<option>${esc(x)}</option>`).join('');$('#playerPos').innerHTML='<option value="">All positions</option>'+pos.map(x=>`<option>${esc(x)}</option>`).join('');filterPlayers()}catch(e){db.innerHTML='<div class="empty">League roster import is temporarily unavailable.</div>'}}
filterPlayers=function(){let q=$('#playerSearch').value.toLowerCase(),t=$('#playerTeam').value,p=$('#playerPos').value;let arr=state.players.filter(x=>(!q||String(x.name||'').toLowerCase().includes(q))&&(!t||x.team===t)&&(!p||x.position===p));$('#playerDb').innerHTML=arr.length?`<div class="playerDirectoryMeta"><b>${arr.length}</b> matching players · <span>★ verified rank-1 depth-chart entry</span></div><div class="tableWrap"><table class="dataTable primeTable"><thead><tr><th>Player</th><th>Team</th><th>Pos</th><th>Depth</th><th>Exp</th><th>College</th></tr></thead><tbody>${arr.map(x=>`<tr><td><button class="linkBtn dbPlayer" data-id="${esc(x.id||'')}" data-name="${esc(x.name)}">${x.starter?'<span class="starterStar">★</span> ':''}${esc(x.name)}</button></td><td>${esc(x.team)}</td><td>${esc(x.position)}</td><td>${x.depth_rank?esc(x.depth_rank):'—'}</td><td>${x.experience==null?'—':esc(x.experience)}</td><td>${esc(x.college||'—')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No matching players.</div>';$$('.dbPlayer').forEach(b=>b.onclick=()=>showProfile(state.players.find(x=>(x.id&&String(x.id)===b.dataset.id)||x.name===b.dataset.name)))};
showProfile=async function(p){if(!p)return;let box=$('#playerProfile');box.innerHTML='<div class="card"><div class="cardBody empty">Loading verified player profile…</div></div>';let full=p;try{if(p.id){let d=await api('/api/player?id='+encodeURIComponent(p.id));if(d.ok)full={...p,...d.player}}}catch(e){}let games=p.games||[],stats=full.stats||[],gamelog=full.gamelog||{};let statGroups={};stats.forEach(s=>(statGroups[s.category||'Season']??=[]).push(s));box.innerHTML=`<div class="primeProfile" style="--pc:${TEAM_COLORS[full.team]||'#28c2ff'}"><div class="primeIdentity"><img src="${esc(full.headshot||playerImg(full))}" onerror="this.style.display='none'"><div><span class="eyebrow">${esc(full.team||'NFL')} · ${esc(full.position||'PLAYER')}</span><h2>${esc(full.name)}</h2><p>${full.starter?'<span class="starterPill">★ STARTER / DEPTH 1</span>':''} ${full.jersey?'<span class="profilePill">#'+esc(full.jersey)+'</span>':''}</p></div></div><div class="primeBio"><div><small>EXPERIENCE</small><b>${full.experience==null?'—':esc(full.experience)+' years'}</b></div><div><small>COLLEGE</small><b>${esc(full.college||'—')}</b></div><div><small>AGE</small><b>${esc(full.age||'—')}</b></div><div><small>HEIGHT</small><b>${esc(full.height||'—')}</b></div><div><small>WEIGHT</small><b>${esc(full.weight||'—')}</b></div><div><small>POSITION</small><b>${esc(full.position_name||full.position||'—')}</b></div></div><div class="card primeSeason"><div class="cardHead"><b>2026 Season Stats</b><span class="badge">${esc(full.stats_source||'SOURCE-GATED')}</span></div><div class="cardBody">${Object.keys(statGroups).length?Object.entries(statGroups).slice(0,6).map(([cat,vals])=>`<div class="profileStatGroup"><small>${esc(cat)}</small><div>${vals.slice(0,12).map(s=>`<span><em>${esc(s.label)}</em><b>${esc(s.value)}</b></span>`).join('')}</div></div>`).join(''):'<div class="empty statEmpty"><b>Season stats unavailable from the connected provider.</b><small>Atlas tried the verified web + core stat surfaces. Missing data stays —.</small></div>'}</div></div>${(gamelog.events||[]).length?`<div class="card profileGameLog"><div class="cardHead"><b>2026 Game Log</b><span>${gamelog.events.length} games</span></div><div class="cardBody gameLogRail">${gamelog.events.slice(0,18).map(e=>`<div><small>${esc(e.date||'2026')}</small><b>${esc(e.label||'Game')}</b></div>`).join('')}</div></div>`:''}${games.length?`<div class="card"><div class="cardHead"><b>Atlas captured games</b><span>${games.length}</span></div><div class="cardBody grid g3">${games.slice(-6).map(g=>`<div class="kpi"><small>${esc(g.status)}</small><strong style="font-size:14px">${Object.entries(g.stats||{}).slice(0,4).map(([k,v])=>`${esc(k.split(':').pop())} ${esc(v)}`).join(' · ')||'—'}</strong></div>`).join('')}</div></div>`:''}<p class="profileSource">Bio and season fields are provider-supplied when available. Missing values remain —.</p></div>`};

