const AI123={data:null,metric:'passing:YDS',team:'',player:'',view:'overview'};
function metric123(p,spec){let [wantCat,wantKey]=spec.split(':');for(const [cat,st] of Object.entries(p.categories||{})){if(!String(cat).toLowerCase().includes(wantCat))continue;for(const [k,v] of Object.entries(st||{})){if(String(k).toUpperCase()===wantKey.toUpperCase())return Number(v)||0}}return 0}
function metricLabel123(spec){return ({'passing:YDS':'Passing yards','passing:TD':'Passing TD','rushing:YDS':'Rushing yards','rushing:TD':'Rushing TD','receiving:YDS':'Receiving yards','receiving:REC':'Receptions','receiving:TD':'Receiving TD','defensive:TOT':'Total tackles','defensive:SACKS':'Sacks','defensive:INT':'Interceptions'})[spec]||spec}
function fmt123(v){return Number.isInteger(Number(v))?Number(v).toLocaleString():Number(v).toFixed(1)}
function archiveGame123(g){let a=(g.teams||[]).find(t=>t.side==='away')||(g.teams||[])[0]||{},h=(g.teams||[]).find(t=>t.side==='home')||(g.teams||[])[1]||{},q=g.quality||{};return `<button class="archiveGame123" data-aigame="${esc(g.id)}"><span class="qualityDot123 q${Math.floor((q.score||0)/20)}"></span><div><small>${g.date?new Date(g.date).toLocaleDateString('en-US',{month:'short',day:'numeric'}):'FINAL'} · ${esc(q.label||'CAPTURED')} ${esc(q.score??'—')}%</small><b>${esc(a.abbr||'—')} ${esc(a.score??'—')} <i>—</i> ${esc(h.score??'—')} ${esc(h.abbr||'—')}</b><em>${esc(g.players)} player rows · ${esc(g.plays)} plays · ${esc(g.drives)} drives</em></div><strong>OPEN →</strong></button>`}
function leaders123(d){let rows=(d.players||[]).map(p=>({...p,value:metric123(p,AI123.metric)})).filter(p=>p.value>0&&(!AI123.team||p.team===AI123.team)).sort((a,b)=>b.value-a.value).slice(0,12);let max=Math.max(1,...rows.map(x=>x.value));return rows.length?`<div class="leaderBars123">${rows.map((p,i)=>`<button data-ai-player="${esc(p.id||'')}" data-ai-name="${esc(p.name)}"><span>${i+1}</span><div><b>${esc(p.name)}</b><small>${esc(p.team||'—')} · ${esc(p.position||'—')} · ${esc(p.games)}G</small><i style="width:${Math.max(3,p.value/max*100)}%"></i></div><strong>${fmt123(p.value)}</strong></button>`).join('')}</div>`:'<div class="empty">No verified Atlas values for this metric yet.</div>'}
function teamTrend123(d){let rows=(d.teams||[]).slice().sort((a,b)=>b.diff_per_game-a.diff_per_game);let mx=Math.max(1,...rows.map(x=>Math.abs(x.diff_per_game)));return `<div class="teamTrend123">${rows.map(t=>`<button data-ai-team="${esc(t.abbr)}"><b>${esc(t.abbr)}</b><span>${esc(t.games)}G · ${esc(t.wins)}-${esc(t.losses)}</span><div><i style="width:${Math.abs(t.diff_per_game)/mx*100}%"></i></div><strong>${t.diff_per_game>0?'+':''}${esc(t.diff_per_game)}</strong></button>`).join('')}</div>`}
function timeline123(d){let gs=(d.games||[]).slice().reverse();return `<div class="timeline123">${gs.map(g=>{let a=(g.teams||[]).find(t=>t.side==='away')||(g.teams||[])[0]||{},h=(g.teams||[]).find(t=>t.side==='home')||(g.teams||[])[1]||{};return `<button data-aigame="${esc(g.id)}"><small>${g.date?new Date(g.date).toLocaleDateString('en-US',{month:'short',day:'numeric'}):'FINAL'}</small><b>${esc(a.abbr)} ${esc(a.score)}–${esc(h.score)} ${esc(h.abbr)}</b><span>${esc(g.quality?.score??'—')}% capture</span></button>`}).join('')}</div>`}
function archiveOverview123(d){let s=d.sample||{};return `<div class="archiveHero123"><div><small>ATLAS-OWNED DATASET</small><h3>${esc(s.final_games||0)} final games are queryable</h3><p>Everything below is calculated only from Atlas final-game archives. Sample sizes stay visible; unavailable values stay unavailable.</p></div><span>READ-ONLY ANALYTICS</span></div><div class="archiveKpis123"><div><small>FINAL GAMES</small><b>${esc(s.final_games||0)}</b></div><div><small>PLAYER ENTITIES</small><b>${esc(s.players||0)}</b></div><div><small>TEAMS</small><b>${esc(s.teams||0)}/32</b></div><div><small>PLAYS CAPTURED</small><b>${Number(s.plays||0).toLocaleString()}</b></div><div><small>DRIVES CAPTURED</small><b>${Number(s.drives||0).toLocaleString()}</b></div></div><div class="archiveGrid123"><section class="atlasPanel123"><header><b>Archive Explorer</b><span>${esc(s.final_games||0)} FINALS</span></header><div class="archiveList123">${(d.games||[]).slice(0,24).map(archiveGame123).join('')}</div></section><section class="atlasPanel123"><header><b>Atlas Timeline</b><span>CAPTURE ORDER</span></header>${timeline123(d)}</section></div>`}
function archiveLeaders123(d){let metrics=[['passing:YDS','Pass Yards'],['passing:TD','Pass TD'],['rushing:YDS','Rush Yards'],['rushing:TD','Rush TD'],['receiving:YDS','Rec Yards'],['receiving:REC','Receptions'],['receiving:TD','Rec TD'],['defensive:TOT','Tackles'],['defensive:SACKS','Sacks'],['defensive:INT','INT']];return `<div class="archiveToolbar123"><select id="aiMetric123">${metrics.map(([v,l])=>`<option value="${v}" ${v===AI123.metric?'selected':''}>${l}</option>`).join('')}</select><select id="aiTeam123"><option value="">All captured teams</option>${(d.teams||[]).map(t=>`<option ${t.abbr===AI123.team?'selected':''}>${esc(t.abbr)}</option>`).join('')}</select><span>Counting stats only · Atlas final-game sample</span></div><div class="archiveGrid123"><section class="atlasPanel123"><header><b>${esc(metricLabel123(AI123.metric))}</b><span>ATLAS SAMPLE LEADERS</span></header>${leaders123(d)}</section><section class="atlasPanel123"><header><b>Team scoring differential</b><span>PER CAPTURED GAME</span></header>${teamTrend123(d)}</section></div>`}
function renderArchiveIntelligence123(){let host=$('#archiveReplay');if(!host||!AI123.data)return;host.innerHTML=`<div class="archiveTabs123"><button data-aiview="overview" class="${AI123.view==='overview'?'active':''}">Explorer</button><button data-aiview="leaders" class="${AI123.view==='leaders'?'active':''}">Sample Leaders</button><button data-aiview="teams" class="${AI123.view==='teams'?'active':''}">Team Trends</button><span>ATLAS ARCHIVE · VERIFIED SAMPLE</span></div>${AI123.view==='overview'?archiveOverview123(AI123.data):AI123.view==='leaders'?archiveLeaders123(AI123.data):`<div class="atlasPanel123"><header><b>Team trend board</b><span>CAPTURED FINALS ONLY</span></header>${teamTrend123(AI123.data)}</div>`}`;$$('[data-aiview]').forEach(b=>b.onclick=()=>{AI123.view=b.dataset.aiview;renderArchiveIntelligence123()});$$('[data-aigame]').forEach(b=>b.onclick=async()=>{await loadSelected(b.dataset.aigame);route({view:'home',gameId:b.dataset.aigame})});$$('[data-ai-team]').forEach(b=>b.onclick=()=>{ATLAS10.team=b.dataset.aiTeam;route({view:'teams10'})});$$('[data-ai-player]').forEach(b=>b.onclick=()=>{let p=(AI123.data.players||[]).find(x=>(x.id&&String(x.id)===b.dataset.aiPlayer)||x.name===b.dataset.aiName);if(p)openPlayer121(p)});let m=$('#aiMetric123'),t=$('#aiTeam123');if(m)m.onchange=e=>{AI123.metric=e.target.value;renderArchiveIntelligence123()};if(t)t.onchange=e=>{AI123.team=e.target.value;renderArchiveIntelligence123()}}
