/* ===== 13.0 ATLAS INTELLIGENCE ENGINE ===== */
function n130(v){let x=num(v);return x==null?0:x}
function impact130(p){let c=String(p.category||'').toLowerCase(),s=p.stats||{},v=0;if(c.includes('passing'))v=n130(s.YDS)*.055+n130(s.TD)*8-n130(s.INT)*7+n130(s.CMP)*.18;if(c.includes('rushing'))v=n130(s.YDS)*.11+n130(s.TD)*8+n130(s.REC)*.35;if(c.includes('receiving'))v=n130(s.YDS)*.12+n130(s.TD)*8+n130(s.REC)*.7;if(c.includes('defens'))v=n130(s.TOT)*1.25+n130(s.SACKS)*5+n130(s.SACK)*5+n130(s.INT)*7+n130(s.PD)*2;return Math.max(0,Math.min(99,Math.round(v)))}
function impactRace130(g){let m={};for(let p of g?.players||[]){let k=`${p.team}|${p.name}`;if(!m[k])m[k]={...p,score:0};m[k].score+=impact130(p)}return Object.values(m).sort((a,b)=>b.score-a.score).slice(0,5)}
function story130(g){if(!g)return 'Select a game to activate Atlas Intelligence.';let a=team(g,'away'),h=team(g,'home'),as=n130(a.score),hs=n130(h.score),lead=as===hs?'The game is tied':`${as>hs?a.abbr:h.abbr} leads by ${Math.abs(as-hs)}`;let plays=g.plays||[],ex=plays.filter(p=>Math.abs(n130(p.statYardage))>=20),turn=plays.filter(p=>/intercept|fumble.*(lost|recover)/i.test(p.text||''));let last=g.drives?.at(-1);return `${lead}${phase(g)==='FINAL'?' at the final whistle':''}. Atlas has captured ${plays.length} plays, including ${ex.length} explosive gains of 20+ yards${turn.length?` and ${turn.length} turnover events`:''}.${last?` The latest drive: ${last.team||'—'}, ${last.plays??'—'} plays for ${last.yards??'—'} yards, ending ${last.result||'—'}.`:''}`}
function winModel130(g){let a=team(g,'away'),h=team(g,'home'),diff=n130(h.score)-n130(a.score),period=Math.max(1,n130(g.period)||1),clock=String(g.clock||'15:00').split(':'),mins=n130(clock[0])+n130(clock[1])/60,remain=Math.max(0,(4-period)*15+mins),leverage=1+(60-remain)/24,home=50+diff*2.4*leverage;if(phase(g)==='FINAL')home=diff>0?100:diff<0?0:50;home=Math.max(1,Math.min(99,home));return {home:Math.round(home),away:Math.round(100-home),label:phase(g)==='FINAL'?'FINAL RESULT':'ƒ ATLAS SCORE/TIME MODEL'}}
function probabilityTimeline130(g){let snaps=(state.history||[]).slice(-24);let pts=[];for(let x of snaps){let gg=x.data||x.game||x;if(!gg?.teams)continue;let w=winModel130(gg);pts.push(w.home)}if(!pts.length)pts=[winModel130(g).home];let W=600,H=130,p=pts.map((v,i)=>`${pts.length===1?W/2:i*(W/(pts.length-1))},${H-(v/100*H)}`).join(' ');return `<div class="wpChart130"><div class="wpGrid130"><span>100%</span><span>50%</span><span>0%</span></div><svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none"><line x1="0" y1="${H/2}" x2="${W}" y2="${H/2}"/><polyline points="${p}"/></svg></div>`}
function drives130(g){let ds=(g?.drives||[]).slice().reverse();return ds.slice(0,10).map((d,i)=>{let y=n130(d.yards),pl=n130(d.plays),yp=pl?y/pl:null;return `<div class="driveIntel130"><span>${ds.length-i}</span><b>${esc(d.team||'—')}</b><div><strong>${esc(d.result||'—')}</strong><small>${esc(d.plays??'—')} plays · ${esc(d.yards??'—')} yd · ${esc(d.time??'—')}${yp!=null?` · ${yp.toFixed(1)} yd/play`:''}</small></div></div>`}).join('')||'<div class="empty">Drive data has not arrived yet.</div>'}
function renderIntelligence130(){let b=$('#intelBody130'),g=state.game;if(!b)return;if(!g){b.innerHTML='<div class="empty">Select a game from Live or Scoreboard to activate the Intelligence Engine.</div>';return}let w=winModel130(g),race=impactRace130(g),a=team(g,'away'),h=team(g,'home'),age=state.lastSync?Math.max(0,Math.round((Date.now()-state.lastSync)/1000)):null;b.innerHTML=`<div class="intelStatus130"><span class="liveOrb130"></span><b>${esc(phase(g))}</b><span>FEED AGE ${age==null?'—':age+'s'}</span><span>${esc(g.source||'CONNECTED FEED')}</span><em>DERIVED MODELS ARE LABELED</em></div><div class="intelGrid130"><section class="intelCard130 story130"><header><b>Game Intelligence</b><span>LIVE NARRATIVE</span></header><div><h3>${esc(a.abbr)} ${esc(a.score)} · ${esc(h.abbr)} ${esc(h.score)}</h3><p>${esc(story130(g))}</p></div></section><section class="intelCard130"><header><b>Win Probability</b><span>${w.label}</span></header><div class="wpScore130"><strong style="color:var(--away)">${esc(a.abbr)} ${w.away}%</strong><strong style="color:var(--home)">${w.home}% ${esc(h.abbr)}</strong></div>${probabilityTimeline130(g)}<small class="modelNote130">Atlas model uses score and game time only. It is not a sportsbook or provider probability.</small></section><section class="intelCard130"><header><b>ATLAS MVP Race</b><span>ƒ IMPACT 0–99</span></header><div class="impactRace130">${race.map((p,i)=>`<button data-intel-player="${esc(p.id||'')}" data-intel-name="${esc(p.name)}"><span>${i+1}</span><div><b>${esc(p.name)}</b><small>${esc(p.team)} · ${esc(p.position||p.category||'—')}</small></div><strong>${p.score}</strong></button>`).join('')||'<div class="empty">Player production has not arrived yet.</div>'}</div></section><section class="intelCard130 drivesCard130"><header><b>Drive Analyzer</b><span>${g.drives?.length||0} CAPTURED</span></header><div>${drives130(g)}</div></section></div>`;$$('[data-intel-player]').forEach(x=>x.onclick=()=>{let p=(g.players||[]).find(z=>(z.id&&String(z.id)===x.dataset.intelPlayer)||z.name===x.dataset.intelName);if(p){route({view:'players'});setTimeout(()=>showProfile(p),50)}})}
