/* ===== ATLAS 15.0 — GM LAB ===== */
const GM150={team:localStorage.getItem('atlasGMTeam')||'BAL',tab:'command',league:null,roster:null,allRosters:null,loading:false};
const GM_POS150={QB:['QB'],RB:['RB','FB'],WR:['WR'],TE:['TE'],OL:['C','G','OG','OT','T'],DL:['DT','DE','NT'],EDGE:['EDGE','OLB'],LB:['LB','ILB'],CB:['CB'],S:['S','FS','SS'],ST:['K','P','LS']};
function gmPos150(pos){pos=String(pos||'').toUpperCase();for(const [room,vals] of Object.entries(GM_POS150))if(vals.includes(pos))return room;return 'OTHER'}
function gmTeamRecord150(ab){let d=GM150.league||{};return (d.standings||[]).find(x=>x.abbr===ab)||(d.teams||[]).find(x=>x.abbr===ab)||{abbr:ab,name:TEAM_NAMES[ab]||ab}}
function gmRooms150(){let ps=GM150.roster?.players||[];let out={};for(const p of ps){let r=gmPos150(p.position);(out[r]??=[]).push(p)}return out}
function gmRoomScore150(room,players){let starters=players.filter(p=>p.starter).length,depth=players.filter(p=>Number(p.depth_rank||99)<=2).length,exp=players.map(p=>Number(p.experience)).filter(Number.isFinite);let avg=exp.length?exp.reduce((a,b)=>a+b,0)/exp.length:0;let expected={QB:1,RB:2,WR:3,TE:1,OL:5,DL:3,EDGE:2,LB:2,CB:3,S:2,ST:3}[room]||1;let coverage=Math.min(1,starters/expected),twoDeep=Math.min(1,depth/(expected*1.8));return Math.round(35+coverage*35+twoDeep*20+Math.min(10,avg*1.3))}
function gmNeedLabel150(score){return score<58?'PRIORITY':score<70?'WATCH':score<82?'STABLE':'STRENGTH'}
function gmPersonnelCard150(p){return `<button class="gmPlayer150" data-gmplayer150="${esc(p.id||'')}" data-gmname150="${esc(p.name)}"><div class="gmAvatar150">${p.headshot||p.id?`<img src="${esc(p.headshot||playerImg(p))}" onerror="this.style.display='none'">`:''}<span>${esc((p.position||'?').slice(0,3))}</span></div><div><b>${esc(p.name)}</b><small>${esc(p.position||'—')} · ${p.starter?'STARTER':p.depth_rank?'DEPTH '+p.depth_rank:'ROSTER'}</small></div><em>${p.experience==null?'—':esc(p.experience)+' YR'}</em></button>`}
function gmSummary150(){let r=gmTeamRecord150(GM150.team),rooms=gmRooms150(),scores=Object.entries(rooms).filter(([k])=>k!=='OTHER').map(([room,ps])=>({room,score:gmRoomScore150(room,ps),count:ps.length})).sort((a,b)=>a.score-b.score),weak=scores.slice(0,3),strong=[...scores].sort((a,b)=>b.score-a.score).slice(0,3),starters=(GM150.roster?.players||[]).filter(p=>p.starter).length;return `<div class="gmCommandHero150" style="--gmteam:${TEAM_COLORS[GM150.team]||'#64c8ff'}"><div><small>GENERAL MANAGER VIEW · ${esc(r.conference||'NFL')} ${esc(r.division||'')}</small><h3>${esc(r.name||TEAM_NAMES[GM150.team])}</h3><p>${esc(r.record||'—')} · Atlas Index ${esc(r.atlasIndex||'—')} · ${starters} verified starters</p></div><div class="gmIndex150"><span>ATLAS INDEX</span><b>${esc(r.atlasIndex||'—')}</b><small>#${esc(r.atlasRank||'—')} LEAGUE</small></div></div><div class="gmMetrics150"><div><small>ROSTERED</small><b>${GM150.roster?.players?.length||0}</b><span>active imported players</span></div><div><small>VERIFIED STARTERS</small><b>${starters}</b><span>depth-chart rank 1</span></div><div><small>POSITION ROOMS</small><b>${scores.length}</b><span>personnel groups mapped</span></div><div><small>DECISION FLAGS</small><b>${scores.filter(x=>x.score<70).length}</b><span>rooms below stable threshold</span></div></div><div class="gmSplit150"><section class="gmPanel150"><header><b>EXECUTIVE NEEDS</b><span>ƒ ROSTER-DERIVED</span></header>${weak.map(x=>`<button data-gmroom150="${x.room}"><strong>${x.room}</strong><div><i style="width:${x.score}%"></i></div><b>${x.score}</b><em>${gmNeedLabel150(x.score)}</em></button>`).join('')}</section><section class="gmPanel150"><header><b>ROSTER STRENGTHS</b><span>DEPTH + EXPERIENCE</span></header>${strong.map(x=>`<button data-gmroom150="${x.room}"><strong>${x.room}</strong><div><i style="width:${x.score}%"></i></div><b>${x.score}</b><em>${gmNeedLabel150(x.score)}</em></button>`).join('')}</section></div><div class="gmSourceGate150"><div><b>CAP + CONTRACTS</b><span>Source-gated</span><p>ATLAS will not invent salary, guarantees or contract years. This module activates only when a reliable contract source is connected.</p></div><div><b>DRAFT CAPITAL</b><span>Source-gated</span><p>Pick inventory stays unavailable until a reliable draft-assets feed is connected.</p></div></div>`}
function gmRoster150(){let ps=GM150.roster?.players||[];let groups=gmRooms150();return `<div class="gmBoardHead150"><div><small>53-MAN PERSONNEL WORKSPACE</small><h3>Roster Board</h3></div><span>${ps.length} PLAYERS · ${ps.filter(p=>p.starter).length} VERIFIED STARTERS</span></div><div class="gmRosterGrid150">${Object.entries(groups).filter(([r])=>r!=='OTHER').map(([room,arr])=>`<section><header><b>${room}</b><span>${arr.length}</span></header>${arr.sort((a,b)=>(Number(a.depth_rank)||9)-(Number(b.depth_rank)||9)).map(gmPersonnelCard150).join('')}</section>`).join('')}</div>`}
function gmRoomsView150(){let rooms=Object.entries(gmRooms150()).filter(([r])=>r!=='OTHER').map(([room,ps])=>({room,ps,score:gmRoomScore150(room,ps)})).sort((a,b)=>a.score-b.score);return `<div class="gmBoardHead150"><div><small>POSITION GROUP HEALTH</small><h3>Position Rooms</h3></div><span>ƒ DERIVED FROM ROSTER DEPTH + EXPERIENCE</span></div><div class="gmRoomGrid150">${rooms.map(x=>`<button data-gmroom150="${x.room}" class="gmRoomCard150"><div><small>${gmNeedLabel150(x.score)}</small><strong>${x.room}</strong><span>${x.ps.length} rostered · ${x.ps.filter(p=>p.starter).length} starters</span></div><b>${x.score}</b><i><em style="width:${x.score}%"></em></i></button>`).join('')}</div>`}
function gmNeeds150(){let rooms=Object.entries(gmRooms150()).filter(([r])=>r!=='OTHER').map(([room,ps])=>({room,ps,score:gmRoomScore150(room,ps)})).sort((a,b)=>a.score-b.score);return `<div class="gmBoardHead150"><div><small>PERSONNEL PRIORITY MATRIX</small><h3>Needs Board</h3></div><span>NO MOCK DATA · NO CONTRACT ASSUMPTIONS</span></div><div class="gmNeeds150">${rooms.map((x,i)=>`<div class="gmNeedRow150"><strong>${String(i+1).padStart(2,'0')}</strong><b>${x.room}</b><div><i style="width:${x.score}%"></i></div><span>${x.score}/100</span><em>${gmNeedLabel150(x.score)}</em><small>${x.ps.filter(p=>p.starter).length} starter${x.ps.filter(p=>p.starter).length===1?'':'s'} · ${x.ps.length} total</small></div>`).join('')}</div>`}
function gmDecisions150(){let rooms=Object.entries(gmRooms150()).filter(([r])=>r!=='OTHER').map(([room,ps])=>({room,ps,score:gmRoomScore150(room,ps)})).sort((a,b)=>a.score-b.score),flags=rooms.slice(0,5);return `<div class="gmBoardHead150"><div><small>FRONT OFFICE WORK QUEUE</small><h3>Decision Desk</h3></div><span>ATLAS PERSONNEL TRIAGE</span></div><div class="gmDecisionGrid150"><section class="gmPanel150"><header><b>REVIEW QUEUE</b><span>AUTO-GENERATED</span></header>${flags.map((x,i)=>`<button data-gmroom150="${x.room}"><strong>0${i+1}</strong><div><b>Review ${x.room} room</b><small>${x.ps.length} players · room score ${x.score}</small></div><em>${gmNeedLabel150(x.score)}</em></button>`).join('')}</section><section class="gmBrief150"><small>ATLAS GM BRIEF</small><h3>${flags.filter(x=>x.score<70).length?`${flags.filter(x=>x.score<70).length} position rooms require attention.`:'Roster structure is currently stable.'}</h3><p>This board is descriptive, not a transaction recommendation. It identifies roster structure worth reviewing from the data ATLAS actually has.</p><div><button data-gmtabgo150="needs">OPEN NEEDS BOARD</button><button data-route="players">OPEN PLAYER UNIVERSE</button></div></section></div>`}

function gmAllTeamRows151(){
  const teams=Object.keys(TEAM_NAMES).sort().map(ab=>{const r=gmTeamRecord150(ab),ro=GM150.allRosters?.[ab],ps=ro?.players||[],rooms={};for(const p of ps){const room=gmPos150(p.position);(rooms[room]??=[]).push(p)}const scores=Object.entries(rooms).filter(([k])=>k!=='OTHER').map(([room,x])=>gmRoomScore150(room,x));const health=scores.length?Math.round(scores.reduce((a,b)=>a+b,0)/scores.length):0;return {ab,r,ps,health,starters:ps.filter(p=>p.starter).length,flags:scores.filter(x=>x<70).length}});
  return teams;
}
function gmAllCommand151(){let rows=gmAllTeamRows151(),loaded=rows.filter(x=>x.ps.length),players=loaded.reduce((n,x)=>n+x.ps.length,0),starters=loaded.reduce((n,x)=>n+x.starters,0),flags=loaded.reduce((n,x)=>n+x.flags,0);return `<div class="gmBoardHead150"><div><small>LEAGUE-WIDE FRONT OFFICE</small><h3>NFL Command Center</h3></div><span>ALL 32 ORGANIZATIONS · ROSTER-DERIVED</span></div><div class="gmLeagueStats151"><div><small>TEAMS LOADED</small><b>${loaded.length}/32</b><span>front offices indexed</span></div><div><small>PLAYERS MAPPED</small><b>${players}</b><span>across imported rosters</span></div><div><small>VERIFIED STARTERS</small><b>${starters}</b><span>depth-chart rank 1</span></div><div><small>REVIEW FLAGS</small><b>${flags}</b><span>rooms below stable threshold</span></div></div>${gmAllTable151(rows)}`}
function gmAllTable151(rows=gmAllTeamRows151()){return `<div class="gmAllTable151"><div class="gmAllRow151 header"><span>TEAM</span><span>ORGANIZATION</span><span>ROSTER</span><span>STARTERS</span><span>HEALTH</span><span>FLAGS</span></div>${rows.map(x=>`<div class="gmAllRow151"><b>${x.ab}</b><button data-gmteamopen151="${x.ab}">${esc(x.r.name||TEAM_NAMES[x.ab])}</button><span>${x.ps.length}</span><span>${x.starters}</span><span>${x.health||'—'}</span><span>${x.flags}</span></div>`).join('')}</div>`}
function gmAllNeeds151(){let items=[];for(const x of gmAllTeamRows151()){let rooms={};for(const p of x.ps){let room=gmPos150(p.position);(rooms[room]??=[]).push(p)}for(const [room,ps] of Object.entries(rooms).filter(([r])=>r!=='OTHER'))items.push({ab:x.ab,name:x.r.name||TEAM_NAMES[x.ab],room,ps,score:gmRoomScore150(room,ps)})}items.sort((a,b)=>a.score-b.score);return `<div class="gmBoardHead150"><div><small>NFL PERSONNEL PRIORITY MATRIX</small><h3>League Needs Board</h3></div><span>ALL TEAMS · NO CONTRACT ASSUMPTIONS</span></div><div class="gmNeeds150">${items.slice(0,64).map((x,i)=>`<div class="gmNeedRow150"><strong>${String(i+1).padStart(2,'0')}</strong><b><button data-gmteamopen151="${x.ab}">${x.ab}</button> · ${x.room}</b><div><i style="width:${x.score}%"></i></div><span>${x.score}/100</span><em>${gmNeedLabel150(x.score)}</em><small>${x.ps.filter(p=>p.starter).length} starters · ${x.ps.length} total</small></div>`).join('')}</div>`}
function gmAllRoster151(){return `<div class="gmBoardHead150"><div><small>NFL ROSTER DIRECTORY</small><h3>All-Team Roster Board</h3></div><span>SELECT A TEAM TO OPEN ITS PERSONNEL BOARD</span></div>${gmAllTable151()}`}
function gmAllRooms151(){let rows=gmAllTeamRows151().sort((a,b)=>a.health-b.health);return `<div class="gmBoardHead150"><div><small>LEAGUE POSITION-ROOM HEALTH</small><h3>Organization Comparison</h3></div><span>COMPOSITE OF ROSTER ROOM SCORES</span></div>${gmAllTable151(rows)}`}
function gmAllDecisions151(){let rows=gmAllTeamRows151().sort((a,b)=>b.flags-a.flags);return `<div class="gmBoardHead150"><div><small>NFL FRONT OFFICE WORK QUEUE</small><h3>League Decision Desk</h3></div><span>DESCRIPTIVE PERSONNEL TRIAGE</span></div>${gmAllTable151(rows)}`}
function gmWireAll151(){document.querySelectorAll('[data-gmteamopen151]').forEach(x=>x.onclick=async()=>{GM150.team=x.dataset.gmteamopen151;localStorage.setItem('atlasGMTeam',GM150.team);GM150.roster=GM150.allRosters?.[GM150.team]||null;await loadGM150(!GM150.roster)})}
async function gmLoadAll151(){if(GM150.allRosters&&Object.keys(GM150.allRosters).length===32)return;GM150.allRosters=GM150.allRosters||{};const teams=Object.keys(TEAM_NAMES);for(let i=0;i<teams.length;i+=8){await Promise.all(teams.slice(i,i+8).map(async ab=>{if(GM150.allRosters[ab])return;try{let r=await api('/api/roster?team='+encodeURIComponent(ab)+'&_='+Date.now());if(r?.ok)GM150.allRosters[ab]=r}catch(e){}}));let b=$('#gmBody150');if(b)b.innerHTML=`<div class="gmLoading150"><div class="spinner143"></div><b>Assembling NFL front office board…</b><span>${Object.keys(GM150.allRosters).length}/32 team rosters loaded</span></div>`}}

function renderGM150(){let b=$('#gmBody150');if(!b||(!GM150.roster&&GM150.team!=='ALL'))return;document.querySelectorAll('[data-gmtab150]').forEach(x=>x.classList.toggle('active',x.dataset.gmtab150===GM150.tab));if(GM150.team==='ALL'){b.innerHTML=GM150.tab==='roster'?gmAllRoster151():GM150.tab==='rooms'?gmAllRooms151():GM150.tab==='needs'?gmAllNeeds151():GM150.tab==='decisions'?gmAllDecisions151():gmAllCommand151();gmWireAll151();wireRoutes();return;}b.innerHTML=GM150.tab==='roster'?gmRoster150():GM150.tab==='rooms'?gmRoomsView150():GM150.tab==='needs'?gmNeeds150():GM150.tab==='decisions'?gmDecisions150():gmSummary150();document.querySelectorAll('[data-gmplayer150]').forEach(x=>x.onclick=()=>{let p=(GM150.roster.players||[]).find(z=>(z.id&&String(z.id)===x.dataset.gmplayer150)||z.name===x.dataset.gmname150);if(p){route({view:'players'});setTimeout(()=>showProfile(p),80)}});document.querySelectorAll('[data-gmroom150]').forEach(x=>x.onclick=()=>{GM150.tab='roster';renderGM150();setTimeout(()=>[...document.querySelectorAll('.gmRosterGrid150 section header b')].find(z=>z.textContent===x.dataset.gmroom150)?.scrollIntoView({behavior:'smooth',block:'center'}),50)});document.querySelectorAll('[data-gmtabgo150]').forEach(x=>x.onclick=()=>{GM150.tab=x.dataset.gmtabgo150;renderGM150()});wireRoutes()}
async function loadGM150(force=false){let b=$('#gmBody150');if(!b||GM150.loading)return;GM150.loading=true;if((!GM150.roster&&GM150.team!=='ALL')||force)b.innerHTML='<div class="gmLoading150"><div class="spinner143"></div><b>Assembling front office board…</b><span>League intelligence + verified roster structure</span></div>';try{GM150.league=GM150.league||await api('/api/league?_='+Date.now());if(GM150.team==='ALL'){await gmLoadAll151();GM150.roster=null}else{let r=GM150.allRosters?.[GM150.team]||await api('/api/roster?team='+encodeURIComponent(GM150.team)+'&_='+Date.now());if(!r?.ok)throw Error('Roster unavailable');GM150.roster=r}let sel=$('#gmTeam150');if(sel){sel.innerHTML=`<option value="ALL" ${GM150.team==='ALL'?'selected':''}>ALL TEAMS · NFL</option>`+Object.keys(TEAM_NAMES).sort().map(a=>`<option value="${a}" ${a===GM150.team?'selected':''}>${a} · ${esc(TEAM_NAMES[a])}</option>`).join('');sel.onchange=async e=>{GM150.team=e.target.value;localStorage.setItem('atlasGMTeam',GM150.team);GM150.roster=GM150.team==='ALL'?null:(GM150.allRosters?.[GM150.team]||null);await loadGM150(true)}}renderGM150()}catch(e){b.innerHTML='<div class="emptyExperience143"><b>GM Lab could not assemble this board.</b><span>League and roster data must be available.</span><button id="retryGM150">Retry GM Lab</button></div>';$('#retryGM150').onclick=()=>loadGM150(true)}finally{GM150.loading=false}}
document.querySelectorAll('[data-gmtab150]').forEach(x=>x.onclick=()=>{GM150.tab=x.dataset.gmtab150;renderGM150()});

/* ===== ATLAS 16.0 — BLACKSITE EXPERIMENTS ===== */
const GMX16={shortlist:JSON.parse(localStorage.getItem('atlasGMShortlist16')||'[]'),notes:JSON.parse(localStorage.getItem('atlasGMNotes16')||'{}'),filter:'ALL',query:''};
function gmSave16(){localStorage.setItem('atlasGMShortlist16',JSON.stringify(GMX16.shortlist));localStorage.setItem('atlasGMNotes16',JSON.stringify(GMX16.notes))}
function gmLeaguePlayers16(){let out=[];for(const [ab,r] of Object.entries(GM150.allRosters||{}))for(const p of (r?.players||[]))out.push({...p,team:ab,room:gmPos150(p.position)});return out}
function gmMatrix16(){let teams=gmAllTeamRows151(),rooms=Object.keys(GM_POS150);let cells=teams.map(t=>{let by={};for(const p of t.ps)(by[gmPos150(p.position)]??=[]).push(p);return {t,s:Object.fromEntries(rooms.map(r=>[r,by[r]?.length?gmRoomScore150(r,by[r]):0]))}});return `<div class="gmBoardHead150"><div><small>LEAGUE PERSONNEL TOPOLOGY · EXPERIMENTAL</small><h3>Personnel Matrix</h3></div><span>32 CLUBS × ${rooms.length} POSITION ROOMS</span></div><div class="x16Legend"><span>STRUCTURAL PRESSURE</span><i></i><span>STABLE</span><i></i><span>DEEP</span></div><div class="x16Matrix"><div class="x16MRow x16MHead"><b>TEAM</b>${rooms.map(r=>`<span>${r}</span>`).join('')}</div>${cells.map(({t,s})=>`<button class="x16MRow" data-gmteamopen151="${t.ab}"><b>${t.ab}</b>${rooms.map(r=>`<span class="x16Heat h${Math.min(9,Math.floor((s[r]||0)/10))}" title="${r} ${s[r]||'—'}">${s[r]||'—'}</span>`).join('')}</button>`).join('')}</div>`}
