function openPalette181(){let old=$('#palette181');if(old){old.remove();return}let o=document.createElement('div');o.id='palette181';o.className='palette181';o.innerHTML=`<div class="paletteBox181"><header><span>ATLAS COMMAND</span><kbd>ESC</kbd></header><input id="paletteInput181" autocomplete="off" placeholder="Search a player, team, game area or workspace…"><div id="paletteResults181"></div><footer><span>↑↓ navigate · Enter open</span><b>18.1 CONNECTED NAVIGATION</b></footer></div>`;document.body.appendChild(o);let input=$('#paletteInput181'),res=$('#paletteResults181'),idx=0,items=[];function draw(){items=paletteItems181(input.value);idx=Math.min(idx,Math.max(0,items.length-1));res.innerHTML=items.map((x,i)=>`<button class="${i===idx?'active':''}" data-pi181="${i}"><span>${x.kind==='team'?`<img src="${esc(logo175(x.ab))}">`:x.kind==='player'?'◉':'↗'}</span><div><b>${esc(x.name)}</b><small>${esc(x.sub)}</small></div><em>${x.kind.toUpperCase()}</em></button>`).join('')||'<div class="paletteEmpty181">No ATLAS destination matched that search.</div>';res.querySelectorAll('button').forEach(b=>b.onclick=()=>go(+b.dataset.pi181))}function go(i){let x=items[i];if(!x)return;o.remove();if(x.kind==='route')route({view:x.view});else if(x.kind==='team'){ATLAS10.team=x.ab;localStorage.setItem('atlas10Team',x.ab);route({view:'teams10'});setTimeout(()=>renderTeamUniverse10(),20)}else if(x.kind==='player'){route({view:'players'});setTimeout(()=>showProfile(x.p),80)}}input.oninput=()=>{idx=0;draw()};input.onkeydown=e=>{if(e.key==='ArrowDown'){e.preventDefault();idx=Math.min(items.length-1,idx+1);draw()}else if(e.key==='ArrowUp'){e.preventDefault();idx=Math.max(0,idx-1);draw()}else if(e.key==='Enter'){e.preventDefault();go(idx)}else if(e.key==='Escape')o.remove()};o.onclick=e=>{if(e.target===o)o.remove()};draw();setTimeout(()=>input.focus(),20)}
