const ATLAS190={version:'19.0',name:'UNIFIED FOOTBALL OS'};
function pct190(v,arr,invert=false){v=num(v);let xs=arr.map(num).filter(x=>x!==null);if(v===null||!xs.length)return null;let n=xs.filter(x=>invert?x>=v:x<=v).length;return Math.max(1,Math.min(99,Math.round(n/xs.length*100)))}
