function spark190(values){let xs=values.map(num).filter(x=>x!==null);if(xs.length<2)return '<div class="sparkEmpty190">Trend builds as game data accumulates.</div>';let lo=Math.min(...xs),hi=Math.max(...xs),rng=hi-lo||1,pts=xs.map((v,i)=>`${(i/(xs.length-1))*100},${34-((v-lo)/rng)*28}`).join(' ');return `<svg class="spark190" viewBox="0 0 100 40" preserveAspectRatio="none"><polyline points="${pts}"/></svg>`}
